  DelayQuadMapper1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        xin1 <= to_signed(0, 44);
      ELSIF enb_1_32_0 = '1' THEN
        xin1 <= XQMapped_signed;
